-- Isolated SPM-163 / SPM-147 waitlist and withdrawal test schema, from the
-- development schema inspected on 30 October 2026: the columns, keys, enums
-- and constraints the registration, offer and notification functions read or
-- write. It is not a complete production schema. The helper functions are
-- loaded from their source migrations, then the SPM-163/147 migrations run
-- whole.

CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;

CREATE TYPE public.user_role AS ENUM ('ORGANISER', 'COORDINATOR', 'VENUE_STAFF', 'TECH_SUPPORT', 'ATTENDEE', 'COORDINATOR_LEAD', 'SAFETY_OFFICER');
CREATE TYPE public.event_status AS ENUM ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'AWAITING_CLARIFICATION', 'APPROVED', 'PLANNING', 'SAFETY_REVIEW', 'CONFIRMED', 'PREPARATION', 'COMPLETED', 'CANCELLED', 'REJECTED');
CREATE TYPE public.notification_type AS ENUM ('STATUS_CHANGE', 'BOOKING_UPDATE', 'EQUIPMENT_UPDATE', 'REGISTRATION_ALERT', 'REGISTRATION_CONFIRMED', 'WAITLIST_JOINED', 'WAITLIST_OFFER', 'EVENT_CANCELLED', 'EVENT_CHANGED', 'EVENT_REMINDER', 'VENUE_SUGGESTION', 'ASSIGNMENT_ENDED');
CREATE TYPE public.registration_status AS ENUM ('REGISTERED', 'WAITLISTED', 'WITHDRAWN');

CREATE TABLE public."user" (
  user_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email varchar(255) NOT NULL,
  name varchar(100) NOT NULL,
  role public.user_role NOT NULL,
  is_active boolean NOT NULL DEFAULT true
);

CREATE TABLE public.organisation (
  organisation_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL
);

CREATE TABLE public.event (
  event_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organiser_id integer NOT NULL REFERENCES public."user" (user_id),
  coordinator_id integer REFERENCES public."user" (user_id),
  organisation_id integer REFERENCES public.organisation (organisation_id),
  title varchar(200) NOT NULL,
  status public.event_status NOT NULL DEFAULT 'DRAFT',
  start_datetime timestamptz,
  end_datetime timestamptz,
  is_published boolean NOT NULL DEFAULT false,
  is_registration_enabled boolean NOT NULL DEFAULT true,
  registration_capacity integer,
  registration_open_at timestamptz,
  registration_close_at timestamptz,
  version integer NOT NULL DEFAULT 1
);

CREATE TABLE public.registration (
  registration_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  attendee_id integer NOT NULL REFERENCES public."user" (user_id) ON DELETE CASCADE,
  event_id integer NOT NULL REFERENCES public.event (event_id) ON DELETE CASCADE,
  registration_status public.registration_status NOT NULL DEFAULT 'REGISTERED',
  registration_datetime timestamptz NOT NULL DEFAULT now(),
  withdrawal_date timestamptz,
  has_attended boolean NOT NULL DEFAULT false,
  dietary_restrictions text,
  accessibility_requirements text,
  CONSTRAINT unique_user_event_registration UNIQUE (attendee_id, event_id)
);

CREATE TABLE public.notification (
  notification_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  event_id integer REFERENCES public.event (event_id) ON DELETE SET NULL,
  title varchar(150) NOT NULL,
  message text NOT NULL,
  type public.notification_type NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  action_key text UNIQUE,
  action_expires_at timestamptz,
  CONSTRAINT notification_action_key_format CHECK (action_key IS NULL OR (length(action_key) <= 200 AND action_key ~ '^[A-Z_]+(:[A-Za-z0-9_.-]+)+$'))
);

CREATE TABLE public.notification_recipient (
  notification_id integer NOT NULL REFERENCES public.notification (notification_id) ON DELETE CASCADE,
  recipient_id integer NOT NULL REFERENCES public."user" (user_id) ON DELETE CASCADE,
  is_read boolean NOT NULL DEFAULT false,
  read_at timestamptz,
  PRIMARY KEY (notification_id, recipient_id)
);

CREATE TABLE public.activity_log (
  log_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id integer REFERENCES public."user" (user_id),
  entity_name varchar(50) NOT NULL,
  entity_id integer NOT NULL,
  action varchar(100) NOT NULL,
  details text,
  "timestamp" timestamptz NOT NULL DEFAULT now(),
  actor_role text,
  changes jsonb,
  audience text NOT NULL DEFAULT 'STAFF_ONLY',
  CONSTRAINT activity_log_actor_check CHECK (user_id IS NOT NULL OR actor_role = 'SYSTEM'),
  CONSTRAINT activity_log_audience_check CHECK (audience IN ('OWNER_ONLY', 'ORGANISER_SAFE', 'STAFF_ONLY'))
);

CREATE TABLE public.idempotency_records (
  actor_id integer NOT NULL REFERENCES public."user" (user_id) ON DELETE CASCADE,
  operation text NOT NULL,
  idempotency_key text NOT NULL,
  request_hash text NOT NULL,
  response jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (actor_id, operation, idempotency_key),
  CONSTRAINT idempotency_records_idempotency_key_check CHECK (idempotency_key ~ '^[A-Za-z0-9_.:-]{8,128}$'),
  CONSTRAINT idempotency_records_request_hash_check CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  CONSTRAINT idempotency_records_operation_check CHECK (operation = ANY (ARRAY['registration.register'::text]))
);
